const degrees=x=>x*180/Math.PI
export const posePolicy=Object.freeze({maxYaw:55,maxPitch:40,assistStartsAt:10,assistFullAt:40,maxAssist:.65,minDominantSmile:.82,minOtherSmile:.15,minSameSideCheek:.5,minSameSideEye:.35,maxInhibition:.2})
// MediaPipe canonical-to-observed matrix is column-major. Euler convention: Rz * Ry * Rx.
export function headPose(matrix){if(!matrix)return{available:false,valid:false,reason:'matrix unavailable'};const m=matrix.data;if(matrix.rows!==4||matrix.columns!==4||m?.length!==16||!Array.from(m).every(Number.isFinite))return{available:true,valid:false,reason:'invalid matrix'};const cols=[0,4,8].map(i=>[m[i],m[i+1],m[i+2]]),lengths=cols.map(c=>Math.hypot(...c));if(lengths.some(l=>l<1e-6))return{available:true,valid:false,reason:'degenerate matrix'};const c=cols.map((v,i)=>v.map(x=>x/lengths[i])),dot=(a,b)=>a.reduce((n,x,i)=>n+x*b[i],0),det=c[0][0]*(c[1][1]*c[2][2]-c[1][2]*c[2][1])-c[1][0]*(c[0][1]*c[2][2]-c[0][2]*c[2][1])+c[2][0]*(c[0][1]*c[1][2]-c[0][2]*c[1][1]);if(Math.abs(dot(c[0],c[1]))>.1||Math.abs(dot(c[0],c[2]))>.1||Math.abs(dot(c[1],c[2]))>.1||det<.9)return{available:true,valid:false,reason:'non-rigid matrix'};const yaw=degrees(Math.asin(Math.max(-1,Math.min(1,-c[0][2])))),pitch=degrees(Math.atan2(c[1][2],c[2][2])),roll=degrees(Math.atan2(c[0][1],c[0][0]));return{available:true,valid:true,yaw,pitch,roll,reason:'model transformation matrix; camera coordinates, not mirrored UI'}}
export function expressionGeometry(result,aspect=1){const pose=headPose(result.facialTransformationMatrixes?.[0]),points=result.faceLandmarks?.[0],needed=[13,14,61,291],valid=needed.every(i=>points?.[i]&&['x','y','z'].every(k=>Number.isFinite(points[i][k])));let mouthOpenness=null;if(valid){const distance=(a,b)=>Math.hypot(a.x-b.x,(a.y-b.y)*aspect,a.z-b.z),width=distance(points[61],points[291]);if(width>1e-6)mouthOpenness=distance(points[13],points[14])/width}return{pose,mouthOpenness,landmarkTrackingConfidence:null,confidenceAvailability:'unavailable: FaceLandmarkerResult has no per-frame tracking confidence',landmarkGeometryValid:valid}}
export function poseCorrection(values,context){const pose=context?.pose;if(!pose?.available)return{weight:0,quality:'pose-unavailable',reason:'legacy bilateral scoring; pose unavailable'};if(!pose.valid||Math.abs(pose.yaw)>posePolicy.maxYaw||Math.abs(pose.pitch)>posePolicy.maxPitch||context.landmarkGeometryValid===false)return{weight:0,quality:'unsupported',reason:'pose/geometry outside provisional support window; suppress new expression classification'};const side=values.mouthSmileLeft>=values.mouthSmileRight?'Left':'Right',corroborated=values['mouthSmile'+side]>=posePolicy.minDominantSmile&&Math.min(values.mouthSmileLeft,values.mouthSmileRight)>=posePolicy.minOtherSmile&&values['cheekSquint'+side]>=posePolicy.minSameSideCheek&&values['eyeSquint'+side]>=posePolicy.minSameSideEye&&Math.max(values.mouthFunnel,values.mouthPucker)<=posePolicy.maxInhibition;const weight=corroborated?Math.max(0,Math.min(1,(Math.abs(pose.yaw)-posePolicy.assistStartsAt)/(posePolicy.assistFullAt-posePolicy.assistStartsAt)))*posePolicy.maxAssist:0;return{weight,side,quality:'valid',reason:weight?'pose-conditioned same-side mouth/cheek/eye compensation':'bilateral scoring; compensation evidence not met'}}
